INSERT INTO questions (id, assessment_id, part_id, subject, question_number, question_text, option_a, option_a_image, option_b, option_b_image, option_c, option_c_image, option_d, option_d_image, image_path, image_path_2, correct_option, created_at, updated_at) VALUES (3374, 57, 167, '9th verbal ability', 12, 'I felt the wall of the tunnel shiver. The master alarm squealed through my earphones. Almost simultaneously, Jack yelled down to me that there was a warning light on. Fleeting but spectacular sights snapped into an out of view, the snow, the shower of debris, the moon, looming close and big, the dazzling sunshine for once unfiltered by layers of air. The last twelve hours before re-entry were particular bone-chilling. During this period, I had to go up in to command module. Even after the fiery re-entry splashing down in 81° water in south pacific, we could still see our frosty breath inside the command module.\nWhich one of the following reasons would one consider as more as possible for the warning lights to be on?', 'There was a shower of debris', '', 'Jack was yelling.', '', 'A catastrophe was imminent', '', 'The moon was looming close and big.', '', '', '', 'C', NOW(), NOW());
